using System.Text.Json.Nodes;
using System.Text.RegularExpressions;
using Modeller.Core;
namespace Modeller.Application;

public sealed class MappingSelections(SnapshotRepository models,SnapshotRepository fhir,ModellingIdentity actor)
{
    private static string S(JsonObject o,string key)=>KnowledgeCorpus.Text(o,key);
    public JsonArray Resolve(string project,JsonArray bindings,bool requireCurrent=true){
        actor.Read(project);if(bindings.Count is <2 or >20)throw new ProcessingException("MAPPING_MODELS_REQUIRED");var items=new List<JsonObject>();var seen=new HashSet<string>(StringComparer.Ordinal);var bytes=0;var standards=new HashSet<string>(StringComparer.Ordinal);
        foreach(var input in bindings){var b=input as JsonObject??throw new ProcessingException("MAPPING_MODEL_INVALID");Data.Keys(b,"standard","projectId","path","revision","sha256","version","origin");foreach(var field in new[]{"standard","projectId","path","revision","sha256","version","origin"})if(S(b,field).Length is <1 or >512)throw new ProcessingException("MAPPING_MODEL_PIN_REQUIRED");var standard=S(b,"standard");if(standard is not("FHIR" or "openEHR")||S(b,"origin") is not("agent-modelled" or "externally-provided")||!Regex.IsMatch(S(b,"sha256"),"^[a-f0-9]{64}$")||!seen.Add(standard+"|"+S(b,"projectId")+"|"+S(b,"path")))throw new ProcessingException("MAPPING_MODEL_INVALID");actor.Read(S(b,"projectId"));var repository=standard=="FHIR"?fhir:models;var artifact=repository.Artifact(S(b,"projectId"),S(b,"path"),S(b,"revision"));var content=Data.Required(artifact,"content");bytes+=System.Text.Encoding.UTF8.GetByteCount(content);if(bytes>4194304)throw new ProcessingException("MAPPING_MODEL_CONTEXT_LIMIT");if(Data.Hash(content)!=S(b,"sha256")||S(artifact,"sha256")!=S(b,"sha256"))throw new ProcessingException("MAPPING_MODEL_PIN_MISMATCH");
            if(standard=="FHIR"){var definition=JsonNode.Parse(content) as JsonObject??throw new ProcessingException("MAPPING_MODEL_INPUT_INVALID");if(S(definition,"resourceType")!="StructureDefinition"||S(definition,"url")==""||S(definition,"type")=="")throw new ProcessingException("MAPPING_MODEL_INPUT_INVALID");var actualVersion=S(definition,"version");if(actualVersion!=""&&actualVersion!=S(b,"version")||actualVersion==""&&S(b,"version")!="sha256-"+Data.Hash(content))throw new ProcessingException("MAPPING_MODEL_PIN_MISMATCH");var fhirConfig=JsonNode.Parse(Data.Required(fhir.Artifact(project,FhirWorkspace.ProjectPath),"content")) as JsonObject??throw new ProcessingException("FHIR_PROJECT_REQUIRED");if(S(definition,"fhirVersion")!=""&&S(definition,"fhirVersion")!=S(fhirConfig,"fhirVersion"))throw new ProcessingException("FHIR_RELEASE_MISMATCH");}
            else{if(!S(b,"path").StartsWith("templates/",StringComparison.Ordinal))throw new ProcessingException("TEMPLATE_REQUIRED");if(content.TrimStart().StartsWith('<')){var document=Imports.Xml(content);if(document.Root?.Name.LocalName!="template"||!document.Descendants().Any(e=>e.Name.LocalName=="definition"))throw new ProcessingException("TEMPLATE_REQUIRED");}else if(!Regex.IsMatch(content.TrimStart(),"^template\\b"))throw new ProcessingException("TEMPLATE_REQUIRED");}
            var current=repository.Artifact(S(b,"projectId"),S(b,"path"));var isCurrent=S(current,"revision")==S(b,"revision")&&S(current,"sha256")==S(b,"sha256");if(requireCurrent&&!isCurrent)throw new ProcessingException("MAPPING_MODELS_STALE");standards.Add(standard);items.Add(new JsonObject{["pin"]=b.DeepClone(),["content"]=content,["current"]=isCurrent,["clinicalApproval"]=false,["blockers"]=new JsonArray()});
        }
        if(standards.Count!=2)throw new ProcessingException("MAPPING_BOTH_STANDARDS_REQUIRED");return new JsonArray(items.OrderBy(i=>S((JsonObject)i["pin"]!,"standard"),StringComparer.Ordinal).ThenBy(i=>S((JsonObject)i["pin"]!,"projectId"),StringComparer.Ordinal).ThenBy(i=>S((JsonObject)i["pin"]!,"path"),StringComparer.Ordinal).Select(i=>(JsonNode)i).ToArray());
    }
    public JsonObject Prepare(string project,JsonArray bindings){actor.Write(project);var items=Resolve(project,bindings);var pins=new JsonArray(items.OfType<JsonObject>().Select(i=>i["pin"]!.DeepClone()).ToArray());var identity=new JsonObject{["purpose"]="mapping-model-selection-v1",["project"]=project,["pins"]=pins};var subject=Data.Hash(HistoricJson.Encode(identity));using var ledger=new AuditLedger();if(ledger.Events(actor.Tenant,subject).Count==0)ledger.Append(actor.Tenant,subject,0,new JsonObject{["type"]="MAPPING_MODEL_SELECTION",["project"]=project,["pins"]=pins.DeepClone(),["actor"]=Imports.Actor(actor),["new_state"]="PENDING"});return Get(subject);}
    public JsonObject Get(string subject){using var ledger=new AuditLedger();var events=ledger.Events(actor.Tenant,subject);if(events.Count==0||events[0]?["type"]?.GetValue<string>()!="MAPPING_MODEL_SELECTION")throw new ProcessingException("GOVERNANCE_SUBJECT_NOT_FOUND");var first=(JsonObject)events[0]!;var project=Data.Required(first,"project");var items=Resolve(project,first["pins"] as JsonArray??throw new ProcessingException("MAPPING_MODELS_REQUIRED"),false);var current=items.OfType<JsonObject>().All(i=>i["current"]?.GetValue<bool>()==true);var state=events[^1]!["new_state"]!.GetValue<string>();return new JsonObject{["subject"]=subject,["project"]=project,["sequence"]=events.Count,["state"]=state,["current"]=current,["mappingConfirmed"]=current&&state=="CONFIRMED",["clinicalApproval"]=false,["items"]=items,["events"]=events,["scope"]="User confirmation of exact supplied models; clinical approval and publication are separate."};}
    public JsonObject Decide(string subject,int expected,string decision,string comment){if(!actor.Human||!(actor.Roles??[]).Intersect(new[]{"modeller","reviewer","approver"},StringComparer.Ordinal).Any())throw new ProcessingException("GOVERNANCE_HUMAN_CONFIRMATION_REQUIRED");var view=Get(subject);var project=Data.Required(view,"project");actor.Write(project);if(view["sequence"]!.GetValue<int>()!=expected)throw new ProcessingException("GOVERNANCE_REVISION_CONFLICT");if(decision is not("CONFIRMED" or "REVOKED")||string.IsNullOrWhiteSpace(comment)||comment.Length>4000)throw new ProcessingException("MAPPING_CONFIRMATION_DECISION_INVALID");if(decision=="CONFIRMED"&&view["current"]?.GetValue<bool>()!=true)throw new ProcessingException("GOVERNANCE_SOURCE_CHANGED");using var ledger=new AuditLedger();ledger.Append(actor.Tenant,subject,expected,new JsonObject{["type"]="MAPPING_MODEL_DECISION",["project"]=project,["actor"]=Imports.Actor(actor),["previous_state"]=view["state"]!.DeepClone(),["new_state"]=decision,["comment"]=comment});return Get(subject);}
    public JsonObject Context(string project,JsonArray bindings,string? subject){var items=Resolve(project,bindings,false);var confirmed=false;if(subject is not null){var view=Get(subject);if(S(view,"project")!=project)throw new ProcessingException("MAPPING_MODEL_PROJECT_MISMATCH");var pins=new JsonArray(items.OfType<JsonObject>().Select(i=>i["pin"]!.DeepClone()).ToArray());var expected=new JsonArray(((JsonArray)view["items"]!).OfType<JsonObject>().Select(i=>i["pin"]!.DeepClone()).ToArray());confirmed=view["mappingConfirmed"]?.GetValue<bool>()==true&&Data.Canonical(pins)==Data.Canonical(expected);}return new JsonObject{["items"]=items,["ready"]=confirmed&&items.OfType<JsonObject>().All(i=>i["current"]?.GetValue<bool>()==true),["mappingConfirmed"]=confirmed,["clinicalReady"]=false,["confirmationSubject"]=subject,["mappingBlockers"]=confirmed?new JsonArray():new JsonArray("HUMAN_MAPPING_MODEL_CONFIRMATION_REQUIRED"),["scope"]="Exact supplied model content and revisions; technical validation does not grant user approval."};}
}
